// Classic カラーパレット定義
// パレット初期化関数
void test_palette_init(RetroColorPalette& palette) {
    palette.setColor(0, 0x0000); // 透明色
    palette.setColor(1, 0xFFFF); // RGB(255,255,255)
    palette.setColor(2, 0xF800); // RGB(248,0,0)
    palette.setColor(3, 0x07C0); // RGB(0,248,0)
    palette.setColor(4, 0x001F); // RGB(0,0,248)
    palette.setColor(5, 0xFFC0); // RGB(248,248,0)
    palette.setColor(6, 0xF81F); // RGB(248,0,248)
    palette.setColor(7, 0x07DF); // RGB(0,248,248)
    palette.setColor(8, 0x8430); // RGB(132,132,132)
    palette.setColor(9, 0xFB20); // RGB(252,100,0)
    palette.setColor(10, 0x8000); // RGB(128,0,0)
    palette.setColor(11, 0x0320); // RGB(0,100,0)
    palette.setColor(12, 0x0010); // RGB(0,0,128)
    palette.setColor(13, 0x8320); // RGB(132,100,0)
    palette.setColor(14, 0x4208); // RGB(66,66,66)
    palette.setColor(15, 0x2104); // RGB(33,33,33)
}

